        .read()
        .unwrap_or_else(|error| error.into_inner());
    let Some(polynomial) = guard.pi_laurent_polynomial.as_deref() else {
        crate::retained_projection_diagnostic::record_missing_form(diagnostic_address);
        return None;
    };
